# train.py - trains one model and saves the best checkpoint + a CSV with loss/accuracy per epoch.
# Example: python train.py --augment --run-name cnn_aug
# Source note: adapted from code generated by Claude (Anthropic), Nov 2026.

import argparse, csv, os, time
import numpy as np, torch, torch.nn as nn
from data import load_gtsrb, get_loaders
from models import build_model

# --- Command-line options: the same script runs every experiment, only the flags change ---
ap = argparse.ArgumentParser()
ap.add_argument("--model", default="cnn", choices=["cnn", "resnet18"])
ap.add_argument("--img-size", type=int, default=48)          # 48 for the CNN, 224 for ResNet
ap.add_argument("--epochs", type=int, default=30)            # maximum number of epochs
ap.add_argument("--lr", type=float, default=1e-3)            # 1e-4 for fine-tuning ResNet
ap.add_argument("--batch-size", type=int, default=64)
ap.add_argument("--patience", type=int, default=5)           # early stopping after 5 epochs without improvement
ap.add_argument("--augment", action="store_true")            # flags are off unless written on the command line
ap.add_argument("--weighted-loss", action="store_true")
ap.add_argument("--freeze-backbone", action="store_true")
ap.add_argument("--run-name", required=True)                 # name used for the checkpoint and result files
args = ap.parse_args()

# --- Setup ---
torch.manual_seed(42); np.random.seed(42)                    # same start weights and shuffling every run
device = "cuda" if torch.cuda.is_available() else "cpu"     # GPU if available (e.g. Colab), else CPU
ds = load_gtsrb()
# pretrained=True for ResNet -> data.py uses ImageNet normalisation
train_dl, val_dl = get_loaders(ds, args.img_size, args.augment, args.model == "resnet18", args.batch_size)
model = build_model(args.model, args.img_size, args.freeze_backbone).to(device)
print("Device:", device, "| Parameters:", sum(q.numel() for q in model.parameters()))  # needed for the report

# --- Optional class weights (--weighted-loss) ---
# w_c = N / (43 * n_c): rare classes get weight > 1, common classes < 1, so mistakes on rare
# classes cost more. With equal class sizes every weight would be exactly 1.
weights = None
if args.weighted_loss:
    counts = np.bincount(np.array(ds["train"]["label"]), minlength=43)
    weights = torch.tensor(counts.sum() / (43 * counts), dtype=torch.float32, device=device)

# --- Loss, optimiser, learning-rate schedule ---
loss_fn = nn.CrossEntropyLoss(weight=weights)                # softmax + log-loss for classification
# Only parameters with requires_grad=True are optimised (matters for frozen ResNet: only fc)
opt = torch.optim.Adam([q for q in model.parameters() if q.requires_grad], lr=args.lr)
sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, args.epochs)  # lr falls smoothly from lr to ~0


def run_epoch(dl, train):
    # One pass over the data. train=True: learn; train=False: only measure (validation).
    # train mode: Dropout on, BatchNorm updates its statistics. eval mode: Dropout off, stored statistics.
    # A frozen backbone is kept in eval mode, so its BatchNorm statistics do not change either.
    model.train(train and not args.freeze_backbone)
    total_loss, correct, n = 0, 0, 0
    with torch.set_grad_enabled(train):                      # no gradients in validation -> faster, less memory
        for x, y in dl:
            x, y = x.to(device), y.to(device)
            out = model(x)                                   # forward pass: class scores [batch, 43]
            loss = loss_fn(out, y)
            if train:
                opt.zero_grad()                              # clear old gradients (PyTorch adds them up)
                loss.backward()                              # backpropagation: gradient of loss for every weight
                opt.step()                                   # update weights in the direction that lowers the loss
            total_loss += loss.item() * len(y)               # weight by batch size (last batch is smaller)
            correct += (out.argmax(1) == y).sum().item()     # argmax = predicted class
            n += len(y)
    return total_loss / n, correct / n                       # average loss, accuracy


# --- Training loop with checkpointing and early stopping ---
os.makedirs("checkpoints", exist_ok=True); os.makedirs("results", exist_ok=True)
best, bad, history = 0, 0, []                                # best val acc, epochs without improvement, log
for epoch in range(1, args.epochs + 1):
    t = time.time()
    tr_loss, tr_acc = run_epoch(train_dl, True)
    va_loss, va_acc = run_epoch(val_dl, False)
    sched.step()                                             # lower the learning rate for the next epoch
    history.append([epoch, tr_loss, tr_acc, va_loss, va_acc, time.time() - t])
    print(f"Epoch {epoch}: train {tr_loss:.3f}/{tr_acc:.3f} | val {va_loss:.3f}/{va_acc:.3f} | {time.time() - t:.0f}s")
    if va_acc > best:
        # New best model: save weights AND args, so test.py knows model type and image size
        best, bad = va_acc, 0
        torch.save({"model": model.state_dict(), "args": vars(args)}, f"checkpoints/{args.run_name}.pt")
    else:
        bad += 1
        if bad >= args.patience:                             # early stopping: no improvement for `patience` epochs
            print("Early stopping"); break

# --- Save the per-epoch log, used for the loss curves in the report ---
with open(f"results/{args.run_name}_history.csv", "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["epoch", "train_loss", "train_acc", "val_loss", "val_acc", "seconds"]); w.writerows(history)
print("Best val acc:", best)
